import { test, expect } from 'bun:test';
import { generateRelease } from '../domain/release.mjs';

const revision = '0123456789abcdef0123456789abcdef01234567';

test('release retains exact valid caller strings', () => {
  expect(generateRelease({ version: ' 1.0.0\n', sourceRevision: revision })).toEqual({
    version: ' 1.0.0\n',
    sourceRevision: '0123456789abcdef0123456789abcdef01234567',
  });
  expect(generateRelease({ version: '1.0.0', sourceRevision: 'a'.repeat(40) })).toEqual({
    version: '1.0.0',
    sourceRevision: 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',
  });
});

const invalidVersions = [
  ['absent', {}],
  ...[undefined, null, 1, false, {}, [], new String('1.0.0'), '', ' ', '\t\r\n', '\u00a0'].map(version => [String(version), { version }]),
];
for (const [label, input] of invalidVersions) {
  test('release rejects invalid version ' + label, () => {
    expect(() => generateRelease({ ...input, sourceRevision: revision })).toThrow(TypeError);
  });
